command:
// Thistlewick: a new Standard raid, with Thistlewick's shopping list on the Raid HUD.
// Run it as the Storyteller once each player owns their Entity: the raid takes every Entity with a player owner.
return game.dontGetForked.raid.start({
  town: "Thistlewick", difficulty: "standard",
  list: [
    { name: "the wedding cake in the shop window", duty: "cook", essential: true },
    { name: "a tea set", duty: "butler", essential: true },
    { name: "a top hat", duty: "tailor", essential: false },
    { name: "a coil of rope", duty: "handyman", essential: false },
    { name: "turnip seed for next year’s lanterns", duty: "gardener", essential: false }
  ],
});
